{
  "name": "@in404/english-improver",
  "version": "1.0.1",
  "description": "English grammar improvement plugin for OpenCode and Claude Code",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "english",
    "grammar",
    "ai",
    "writing-assistant",
    "language-learning",
    "esl"
  ],
  "main": "dist/opencode-plugin.js",
  "type": "module",
  "files": [
    "dist/",
    "src/",
    "postinstall.mjs",
    "commands/",
    "skills/",
    ".claude-plugin/",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "postinstall": "node postinstall.mjs",
    "prepublishOnly": "npm run build"
