  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/in404/english-improver.git"
  },
  "homepage": "https://github.com/in404/english-improver#readme",
  "bugs": {
    "url": "https://github.com/in404/english-improver/issues"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.2.1"
  },
  "engines": {
    "node": ">=18.0.0"
